using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;
using ErpSystem.Core.Entities.Base;
using ErpSystem.Core.Entities.Finance;

namespace ErpSystem.Core.Entities.Finance.FixedAssets
{
    /// <summary>
    /// Represents a calculated depreciation expense for a specific fiscal period.
    /// generated by the Depreciation Engine.
    /// </summary>
    public class AssetDepreciationSchedule : TenantEntity
    {
        [Required]
        public Guid FixedAssetId { get; set; }
        public virtual FixedAsset FixedAsset { get; set; } = null!;

        [Required]
        public Guid FiscalPeriodId { get; set; }
        public virtual FiscalPeriod FiscalPeriod { get; set; } = null!;

        /// <summary>
        /// The depreciation amount calculated for this period
        /// </summary>
        [Required]
        [Column(TypeName = "decimal(18,2)")]
        public decimal DepreciationAmount { get; set; }

        /// <summary>
        /// The accumulating depreciation total AFTER this entry is applied
        /// </summary>
        [Column(TypeName = "decimal(18,2)")]
        public decimal AccumulatedDepreciation { get; set; }

        /// <summary>
        /// The Net Book Value AFTER this entry is applied
        /// </summary>
        [Column(TypeName = "decimal(18,2)")]
        public decimal NetBookValue { get; set; }

        // --- Status ---

        public bool IsPosted { get; set; } = false;
        public DateTime? PostedDate { get; set; }

        /// <summary>
        /// Link to the GL Journal Entry where this expense was booked
        /// </summary>
        public Guid? JournalEntryId { get; set; }
        public virtual JournalEntry? JournalEntry { get; set; }

        public bool IsProjected { get; set; } = false; // True if this is a future forecast
    }
}
